@param directory The directory to save the secret file.
@param filename The filename of the secret file.
@param content The content of the secret file.
*/
void save_secrete_file(const char *directory, const char *filename, const char *content) {
    // Basic validation for NULL pointers.
    if (directory == NULL || filename == NULL || content == NULL) {
        return;
    }

    // Prevent directory traversal by checking for '/' or '..' in filename.
    if (strchr(filename, '/') != NULL || strstr(filename, "..") != NULL) {
        return;
    }

    // Construct the full path to the file.
    // Use a buffer that can accommodate the directory, filename, and separator.
    // PATH_MAX is a good choice for maximum path length.
    char filepath[PATH_MAX];
    int written = snprintf(filepath, sizeof(filepath), "%s/%s", directory, filename);

    // Check if snprintf truncated the path or if there was an error.
    if (written < 0 || written >= sizeof(filepath)) {
        return;
    }

    // Check if the directory exists and is writable.
    // This is important to ensure the file is saved in the intended location.
    struct stat st;
    if (stat(directory, &st) == -1) {
        // Directory does not exist or is inaccessible.
        return;
    }
    if (!S_ISDIR(st.st_mode)) {
        // The provided path is not a directory.
        return;
    }
    // Check for symbolic link in directory to prevent traversal.
    if (S_ISLNK(st.st_mode)) {
        return;
    }
    if (access(directory, W_OK) == -1) {
        // Directory is not writable.
        return;
    }

    // Open the file in write mode.
    // Use O_CREAT | O_WRONLY | O_EXCL to ensure atomicity and prevent overwriting.
    // S_IRUSR | S_IWUSR sets permissions to owner read/write.
    int fd = open(filepath, O_CREAT | O_WRONLY | O_EXCL, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        // Handle error if file cannot be opened or already exists.
        return;
    }

    // Write the content to the file.
    ssize_t bytes_written = write(fd, content, strlen(content));
    if (bytes_written == -1 || (size_t)bytes_written != strlen(content)) {
        // Handle error if content cannot be written.
        close(fd);
        unlink(filepath); // Clean up partially written file
        return;
    }

    // Close the file descriptor.
    if (close(fd) != 0) {
        // Handle error if closing the file fails.
        unlink(filepath); // Clean up file if closing fails
        return;
    }

    // The permissions are already set during file creation with open().
    // No need for chmod if using O_CREAT with mode.
}
